def subtract_busy(avail, busy, work_start=WORK_START, work_end=WORK_END):
    busy = sorted((max(work_start, s), min(work_end, e)) for s, e in busy if e > work_start and s < work_end)
    free = []
    cur = work_start
    for s, e in busy:
